const D = { density: .6, energy: .72, speed: 1, scale: 1, hue: 200, x: .5, y: .5, trail: .55, style: 'streamflow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:v>b?b:v;
const style = P.style, light = (style==='blueprint' || style==='ink');

// ---- coarse trail buffer (half-canvas, HSB), size-keyed cache ----
const BW = Math.min(720, Math.max(120, Math.round(W*0.6)));
const BH = Math.max(80, Math.round(BW*H/W));
if (!S.buf || S.bw!==BW || S.bh!==BH){
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(BW, BH); S.buf.pixelDensity(1);
  S.buf.colorMode(HSB,360,100,100,100);
  S.bw=BW; S.bh=BH; S.freshBuf = true;
}

// ---- seed hash + tracer arrays ----
const fr = i => { const s = Math.sin(i*127.1 + (P.seed|0)*311.7)*43758.5453; return s - Math.floor(s); };
const NMAX = 1500;
const N = Math.round(300 + clp(P.density,0,1)*1200);
if (!S.tx || S.tx.length!==NMAX){ S.tx=new Float32Array(NMAX); S.ty=new Float32Array(NMAX); S.age=new Float32Array(NMAX); S.seedUsed=null; }

// ---- ODE system registry (topology cycles on K.section) ----
// each: fn(x,y,pr)->[dx,dy]; view center cx,cy + radius R; fixed points [x,y,type]
const SYS = [
  { name:'PENDULUM',      cx:0, cy:0, R:3.5,  vs:2.2,
    fn:(x,y,d)=>[y, -Math.sin(x) - d*y],
    fx:[[0,0,'center'],[Math.PI,0,'saddle'],[-Math.PI,0,'saddle']] },
  { name:'VAN DER POL',   cx:0, cy:0, R:3.4,  vs:2.6,
    fn:(x,y,m)=>[y, m*(1-x*x)*y - x],
    fx:[[0,0,'source']] },
  { name:'DUFFING',       cx:0, cy:0, R:1.95, vs:1.6,
    fn:(x,y,d)=>[y, x - x*x*x - d*y],
    fx:[[0,0,'saddle'],[1,0,'sink'],[-1,0,'sink']] },
  { name:'LOTKA-VOLTERRA',cx:1, cy:1, R:0.98, vs:0.9,
    fn:(x,y)=>{ const xx=Math.max(0.02,x), yy=Math.max(0.02,y); return [xx*(1.1-yy), -yy*(1.1-xx)]; },
    fx:[[1.1,1.1,'center'],[0,0,'saddle']] }
];
const sec = K.section|0;
const sys = SYS[((sec % SYS.length)+SYS.length)%SYS.length];
// slow drift of the system's control parameter on K.t (never re-phases)
let pr;
if (sys.name==='PENDULUM')      pr = 0.06 + 0.10*(0.5+0.5*Math.sin(K.t*0.11));
else if (sys.name==='VAN DER POL') pr = 1.6 + 1.1*(0.5+0.5*Math.sin(K.t*0.09));
else if (sys.name==='DUFFING')  pr = 0.12 + 0.16*(0.5+0.5*Math.sin(K.t*0.13));
else pr = 0;

const R = sys.R, cx = sys.cx, cy = sys.cy;

// ---- world<->buffer mapping ----
const bcx = clp(P.x,0,1)*BW, bcy = clp(P.y,0,1)*BH;
const bs = Math.min(BW,BH) * clp(P.scale,0.3,3) * 0.44 / R;
const toBX = x => bcx + (x-cx)*bs;
const toBY = y => bcy - (y-cy)*bs;

// ---- (re)seed all tracers on seed change ----
function spawn(i, salt){
  const a = fr(i*2+salt*7.13), b = fr(i*2+1+salt*3.71);
  S.tx[i] = cx + (a*2-1)*R*0.98;
  S.ty[i] = cy + (b*2-1)*R*0.98;
  S.age[i] = fr(i+salt*17.7)*140;
}
if (S.seedUsed !== (P.seed|0)){ S.seedUsed = (P.seed|0); S.spawn=0; for (let i=0;i<NMAX;i++) spawn(i,1); }

// ---- ground / fade tone per style ----
const g = S.buf;
let gH,gS,gB;
if (style==='streamflow'){ gH=255; gS=54; gB=12; }
else if (style==='aurora'){ gH=235; gS=50; gB=11; }
else if (style==='ember'){  gH=16;  gS=68; gB=11; }
else if (style==='blueprint'){ gH=214; gS=78; gB=26; }
else { gH=42; gS=9; gB=86; } // ink cream

if (S.freshBuf){ g.push(); g.noStroke(); g.fill(gH,gS,gB,100); g.rect(0,0,BW,BH); g.pop(); S.freshBuf=false; }

// trail persistence: higher trail -> lower fade alpha -> longer streaks
const fadeA = light ? (7 + (1-clp(P.trail,0,1))*20) : (5 + (1-clp(P.trail,0,1))*16);
g.push();
g.noStroke(); g.blendMode(BLEND);
g.fill(gH,gS,gB, fadeA);
g.rect(0,0,BW,BH);

// ---- advect tracers, draw hued-by-speed segments ----
const dt = 0.028 * clp(P.speed,0.15,3) * (sys.name==='LOTKA-VOLTERRA'?1.4:1.0);
const vs = sys.vs;
const bri = 55 + clp(P.energy,0,1)*45 + A.rms*30 + K.intensity*8;
const aBoost = 1 + A.bass*0.7 + K.pulse*0.25*clp(P.energy,0,1);
const maxStep = R*0.11; // clamp world step so stiff fields never explode

if (!light) g.blendMode(ADD);
const salt = 2 + (sec*0.37);
for (let i=0;i<N;i++){
  let x=S.tx[i], y=S.ty[i];
  const ox=toBX(x), oy=toBY(y);
  // RK2 midpoint
  let k1=sys.fn(x,y,pr);
  let mx=x+k1[0]*dt*0.5, my=y+k1[1]*dt*0.5;
  let k2=sys.fn(mx,my,pr);
  let vx=k2[0], vy=k2[1];
  const sp=Math.hypot(vx,vy);
  // clamp step length
  let stepL=sp*dt; let sc=1; if (stepL>maxStep) sc=maxStep/stepL;
  x += vx*dt*sc; y += vy*dt*sc;
  S.age[i]++;
  const bad = !isFinite(x)||!isFinite(y)|| Math.abs(x-cx)>R*2.2 || Math.abs(y-cy)>R*2.2;
  const old = S.age[i] > (150 + fr(i)*120);
  if (bad || old || (fr(i+ (S.spawn|0)) < (0.010+clp(P.density,0,1)*0.018))){
    spawn(i, salt + (S.spawn||0)*0.019); S.spawn=(S.spawn||0)+1;
    continue;
  }
  S.tx[i]=x; S.ty[i]=y;
  const nx=toBX(x), ny=toBY(y);
  // hue by normalized speed
  const sn = clp(sp/vs, 0, 1);
  let hh, ss, bb, wa, wt;
  if (style==='streamflow'){ hh=(P.hue + 150 - sn*150 + 360)%360; ss=88; bb=bri; wa=32*aBoost; wt=1.05; }
  else if (style==='aurora'){ hh=(120 + sn*160 + P.hue*0.15)%360; ss=70; bb=bri*0.95; wa=22*aBoost; wt=1.9; }
  else if (style==='ember'){ hh=(6 + sn*46)%360; ss=90-sn*18; bb=bri; wa=30*aBoost; wt=1.15; }
  else if (style==='blueprint'){ hh=195; ss=14+sn*20; bb=100; wa=46; wt=1.0; }
  else { hh=(P.hue*0.1+28)%360; ss=16; bb=14; wa=40; wt=1.1; } // ink dark stroke
  g.stroke(hh,ss,bb,wa);
  g.strokeWeight(wt);
  g.line(ox,oy,nx,ny);
}
g.blendMode(BLEND);
g.pop();

// ---- composite buffer to full canvas ----
push();
if (P.alpha < 100){ tint(0,0,100,P.alpha); }
image(g, 0, 0, W, H);
pop();

// ================= main-canvas overlay: nullclines + fixed pts =================
const scX = x => clp(P.x,0,1)*W + (x-cx)*(u*clp(P.scale,0.3,3)*0.44/R);
const scY = y => clp(P.y,0,1)*H - (y-cy)*(u*clp(P.scale,0.3,3)*0.44/R);

// nullclines: generic zero-crossing scan of dx (x-null) and dy (y-null)
push();
noStroke();
const GX=44, GY=30;
const nA = 12 + P.energy*16;
for (let gy=0; gy<GY; gy++){
  for (let gx=0; gx<GX; gx++){
    const wx = cx + ((gx+0.5)/GX*2-1)*R*1.02;
    const wy = cy + ((gy+0.5)/GY*2-1)*R*1.02;
    const wx2 = cx + ((gx+1.5)/GX*2-1)*R*1.02;
    const wy2 = cy + ((gy+1.5)/GY*2-1)*R*1.02;
    const f00=sys.fn(wx,wy,pr), f10=sys.fn(wx2,wy,pr), f01=sys.fn(wx,wy2,pr);
    // dx = 0 crossing (horizontal neighbor)
    if (f00[0]*f10[0] < 0){
      const px=scX((wx+wx2)*0.5), py=scY(wy);
      if (px>-5&&px<W+5&&py>-5&&py<H+5){
        fill(light?(214):(P.hue+150)%360, light?70:70, light?100:96, nA);
        circle(px,py, light?2.2:2.6);
      }
    }
    // dy = 0 crossing (vertical neighbor)
    if (f00[1]*f01[1] < 0){
      const px=scX(wx), py=scY((wy+wy2)*0.5);
      if (px>-5&&px<W+5&&py>-5&&py<H+5){
        fill(light?(28):(P.hue+30)%360, light?60:80, light?24:100, nA);
        circle(px,py, light?2.2:2.4);
      }
    }
  }
}
pop();

// fixed points: glowing markers (shadowBlur on few shapes only)
push();
const spark = 1 + A.treble*0.9 + K.pulse*0.5;
for (let f=0; f<sys.fx.length; f++){
  const fp=sys.fx[f], px=scX(fp[0]), py=scY(fp[1]);
  if (px<-20||px>W+20||py<-20||py>H+20) continue;
  let mh, ms, mb;
  const ty=fp[2];
  if (ty==='center'){ mh=light?214:0; ms=light?30:0; mb=100; }
  else if (ty==='sink'){ mh=light?214:38; ms=light?70:90; mb=100; }
  else if (ty==='source'){ mh=light?214:320; ms=light?70:85; mb=100; }
  else { mh=light?24:190; ms=light?70:80; mb=100; } // saddle
  const rr = u*0.012*(0.8+0.4*Math.sin(K.t*1.3+f));
  drawingContext.shadowBlur = light?0:18*spark;
  drawingContext.shadowColor = 'rgba(255,255,255,0.7)';
  noFill(); stroke(mh,ms,mb, light?90:80); strokeWeight(1.6);
  circle(px,py, rr*2.4);
  drawingContext.shadowBlur = 0;
  noStroke(); fill(mh,ms,light?30:100, 95);
  circle(px,py, rr);
  if (ty==='saddle'){ // cross-hair separatrix hint
    stroke(mh,ms,mb, light?55:45); strokeWeight(1); noFill();
    line(px-rr*2.2,py, px+rr*2.2,py); line(px,py-rr*2.2, px,py+rr*2.2);
  }
}
drawingContext.shadowBlur=0;
pop();

// faint system label (the "map of a differential equation" flavor; evolves w/ section)
push();
noStroke();
textFont('monospace');
textSize(u*0.026);
textAlign(LEFT,TOP);
fill(light?214:0, light?60:0, light?30:100, light?55:40);
text(sys.name, u*0.03, u*0.03);
textSize(u*0.016);
fill(light?214:0, light?50:0, light?35:100, light?45:30);
text("phase portrait / sec "+sec, u*0.03, u*0.03 + u*0.034);
pop();

blendMode(BLEND);
